#define _GNU_SOURCE
#define _POSIX_C_SOURCE 200809L

/*
 * normalize.c - Command normalisation with typed wildcard lattice.
 *
 * Classifies each token into the most specific type in the lattice.
 * Provides join and compatibility tables for policy generation and
 * verification.
 *
 * NOTE: st_type_join and st_type_compatible are generated by
 * tools/gen_lattice_tables.py from a declarative lattice definition in that
 * script. Do not edit these tables by hand; instead update the lattice
 * definition and regenerate.
 */

